                          onChange={(e) => handleCambioCampo(sede.nombre, 'banco_bcp', 'cci', e.target.value)}
                          className="w-full bg-[#040914] border border-slate-800 p-2 rounded-lg text-white font-mono text-[11px]"
                        />
                        <input
                          type="text"
                          placeholder="Titular de la Cuenta"
